// Expo config plugin: declare packages/core as an input of the Android JS
// bundle task.
//
// WHY A PLUGIN AND NOT AN EDIT TO android/app/build.gradle: `android/` is
// generated by `expo prebuild` and is gitignored. A change made there is
// untracked and is destroyed by the next `prebuild --clean` — which would
// silently reintroduce the bug below. Anything the native build needs has to be
// expressed here so it is re-applied on every prebuild.
//
// THE BUG: the React Native bundle task derives its inputs from `react.root`,
// which defaults to the app directory. This app's bundle is also built from
// packages/core, which lives outside it, so Gradle cannot see those files. Edit
// core, rebuild, and createBundleReleaseJsAndAssets reports UP-TO-DATE and
// reuses the previous bundle. That is not a slow build, it is a wrong one, and
// it is silent — it shipped two byte-identical APKs from two different source
// trees before anyone noticed.
//
// Pointing `react.root` at the workspace root instead does NOT work: the repo
// root's package.json is the web app, so Expo CLI bundles that. Don't retry it.
const { withAppBuildGradle } = require('@expo/config-plugins');

const MARKER = 'dripCoreSources';

const BLOCK = `
// ── Monorepo: make packages/core a tracked input of the JS bundle ─────────────
// Generated by apps/mobile/plugins/withCoreBundleInput.js — edit that, not this.
// Without it, Gradle cannot see @drip/core and silently reuses a stale bundle.
//
// The path resolves from rootDir (apps/mobile/android), NOT from this file's
// own directory: file("../../../…") from app/ lands in apps/, which yields an
// EMPTY file tree and tracks nothing — the same silent failure wearing a
// different hat. Hence the assertion rather than trusting the path.
def dripCoreSrc = file("\$rootDir/../../../packages/core/src")
if (!dripCoreSrc.isDirectory()) {
    throw new GradleException(
        "packages/core/src not found at \${dripCoreSrc}. The JS bundle depends on " +
        "@drip/core; without this input Gradle will silently ship a stale bundle. " +
        "Fix the path rather than removing the check.")
}
tasks.configureEach { task ->
    if (task.name.startsWith("createBundle") && task.name.endsWith("JsAndAssets")) {
        task.inputs.dir(dripCoreSrc)
            .withPropertyName("${MARKER}")
            .withPathSensitivity(PathSensitivity.RELATIVE)
    }
}
`;

module.exports = function withCoreBundleInput(config) {
  return withAppBuildGradle(config, (cfg) => {
    if (cfg.modResults.language !== 'groovy') {
      throw new Error('withCoreBundleInput: expected a Groovy build.gradle');
    }
    // Idempotent: prebuild can run repeatedly against an existing file.
    if (!cfg.modResults.contents.includes(MARKER)) {
      cfg.modResults.contents += BLOCK;
    }
    return cfg;
  });
};
